class Solution {
    vector<int> tree;
    int size;

    int query(int v, int tl, int tr, int val) {
        if (tree[v] < val) return -1;
        if (tl == tr) return tl;
        int tm = (tl + tr) / 2;
        if (tree[2 * v] >= val) return query(2 * v, tl, tm, val);
        return query(2 * v + 1, tm + 1, tr, val);
    }

    void update(int v, int tl, int tr, int pos) {
        if (tl == tr) {
            tree[v] = 0;
            return;
        }
        int tm = (tl + tr) / 2;
        if (pos <= tm) update(2 * v, tl, tm, pos);
        else update(2 * v + 1, tm + 1, tr, pos);
        tree[v] = max(tree[2 * v], tree[2 * v + 1]);
    }

public:
    int numOfUnplacedFruits(vector<int>& fruits, vector<int>& baskets) {
        int n = baskets.size();
        size = 1;
        while (size < n) size *= 2;
        tree.assign(2 * size, 0);
        for (int i = 0; i < n; i++) tree[size + i] = baskets[i];
        for (int i = size - 1; i >= 1; i--)
            tree[i] = max(tree[2 * i], tree[2 * i + 1]);

        int unplaced = 0;
        for (int f : fruits) {
            int idx = query(1, 0, size - 1, f);
            if (idx == -1 || idx >= n) unplaced++;
            else update(1, 0, size - 1, idx);
        }
        return unplaced;
    }
};
